import sys
import math

def input_parse_expression(input_lines, i):
	(n, m, k) = map(int, input_lines[2 * i + 1].split())
	a = map(int, input_lines[2 * i + 2].split())
	return (n, m, k, a)

def solve(test_case_input):
	(n, m, k, a) = test_case_input
	if m < k:
		return 'NO'
	max_a_allowed = n // k
	num_1_gt_allowed = n % k
	for ai in a:
		if ai - max_a_allowed > 1:
			return 'NO'
		if ai - max_a_allowed == 1:
			num_1_gt_allowed -= 1
		if num_1_gt_allowed < 0:
			return 'NO'
	return 'YES'

def main():
	input_str = sys.stdin.read()
	input_lines = input_str.strip().split('\n')
	n_cases = int(input_lines[0])
	for i in range(n_cases):
		test_case_input = input_parse_expression(input_lines, i)
		solution = solve(test_case_input)
		print(solution)
main()
